class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        vector<long long> sq;
        sq.reserve(nums.size());
        for (int x : nums) sq.push_back(1LL * x * x);
        sort(sq.rbegin(), sq.rend());
        int k = (sq.size() + 1) / 2;
        long long ans = 0;
        for (int i = 0; i < (int)sq.size(); ++i)
            ans += (i < k ? sq[i] : -sq[i]);
        return ans;
    }
};

