class Solution {
    public long maxAlternatingSum(int[] nums) {
        int n = nums.length;
        long[] sq = new long[n];
        for (int i = 0; i < n; i++) sq[i] = (long) nums[i] * nums[i];
        Arrays.sort(sq);
        long ans = 0;
        int k = (n + 1) / 2;
        for (int i = 0; i < n; i++)
            ans += (i < n - k ? -sq[i] : sq[i]);
        return ans;
    }
}

