class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        const int MAXV = 40000;
        vector<int> cnt(MAXV + 1, 0);
        for (int x : nums) cnt[abs(x)]++;
        long long k = (nums.size() + 1) / 2, ans = 0;
        for (int v = MAXV; v >= 0; --v) {
            if (!cnt[v]) continue;
            long long take = min<long long>(cnt[v], k);
            ans += 1LL * v * v * take;
            k -= take;
            ans -= 1LL * v * v * (cnt[v] - take);
        }
        return ans;
    }
};

